/**
 * 使用TAF-JCE数据格式作为RPC协议的服务端协议解析器
 *  修改scoped,并且修改底层协议
 */
var Taf          = require("@taf/taf-stream");
var TafPacket    = require("./BasePacketFJce.js").taf;

var stream = function () {
    this._name      = "taf";
}
stream.prototype.__defineGetter__("name", function () { return this._name; });

module.exports = stream;

/**
 * 服务端的打包代码
 *
 * 根据传入数据进行打包的方法
 */
stream.prototype.compose = function ($protoMessage) {
    //$protoMessage的结构参考taf-rpc模块中的ProtoMessage结构体
    return ($protoMessage.origin.iVersion == 2)?this.composeWUP($protoMessage):this.composeJCE($protoMessage);
}

stream.prototype.composeJCE = function ($protoMessage) {
    //01 根据上层协议知道，客户端采用Jce格式进行编解码，此时按照Jce格式处理数据 （客户端sBuffer中可以是jce或者json）
    var response = new TafPacket.BasePacket();
    response.iVersion     = $protoMessage.origin.iVersion;
    response.cPacketType  = 0;
    response.iMessageType = $protoMessage.origin.iMessageType;
    response.iRequestId   = $protoMessage.origin.iRequestId;
    response.sBuffer      = $protoMessage.sBuffer?$protoMessage.sBuffer:response.sBuffer; //兼容老版本
    response.iRet         = $protoMessage.origin.iRet;          //框架层的错误代码
    response.sResultDesc  = $protoMessage.origin.sResultDesc;          //框架层的错误消息

    if ($protoMessage.property && $protoMessage.property.context) { //服务端需要返回附加数据
        for (var key in $protoMessage.property.context) {
            response.context.insert(key.toString(), $protoMessage.property.context[key].toString());
        }
    }

    //02 将TafPacket.ResponsePacket打包
    var os = new Taf.JceOutputStream();
    os.setHeaderLength(0);
    response._writeTo(os);
    os.setHeaderLength(os.getBinBuffer().length);

    return os.getBinBuffer().toNodeBuffer();
}

stream.prototype.composeWUP = function ($protoMessage) {
    //根据上层协议知道，客户端采用Wup格式进行编解码，此时按照Wup格式处理数据
    var response = new TafPacket.BasePacket();
    response.iVersion     = $protoMessage.origin.iVersion;
    response.cPacketType  = 0;
    response.iMessageType = $protoMessage.origin.iMessageType;
    response.iRequestId   = $protoMessage.origin.iRequestId;
    response.sServantName = $protoMessage.origin.sServantName;
    response.sFuncName    = $protoMessage.origin.sFuncName;
    response.sBuffer      = $protoMessage.sBuffer;
    response.iRet         = $protoMessage.origin.iRet;          //框架层的错误代码
    response.sResultDesc  = $protoMessage.origin.sResultDesc;          //框架层的错误消息

//    response.status.insert("STATUS_RESULT_CODE", $protoMessage.iResultCode.toString());     //框架层的错误代码
//    response.status.insert("STATUS_RESULT_DESC", $protoMessage.sResultDesc);                //框架层的错误消息

    if ($protoMessage.sBuffer === undefined || $protoMessage.sBuffer.length === 0) {
        var attr = new Taf.UniAttribute();
        attr.wupVersion  = $protoMessage.origin.iVersion;
        response.sBuffer = attr.encode();
    }

    //将TafPacket.BasePacket打包
    var os = new Taf.JceOutputStream();
    os._binBuffer.writeInt32(0);
    response._writeTo(os);

    var lenBuffer = Buffer.alloc(4);
    lenBuffer.writeInt32BE(os.getBinBuffer().length, 0);
    os._binBuffer.replace(lenBuffer, 0, 4);

    return os.getBinBuffer().toNodeBuffer();
}

/**
 * 服务端的解包代码
 *
 * 网络收取包之后，填入数据判断是否完整包
 */
stream.prototype.feed = function (networkBuffer, message) {

    var Length = networkBuffer.readLength();

    // 如果碰到超大的数据包（超过10M）或者超小的数据包（不满足最小长度要求），直接丢弃当前数据包
    if (Length > 1e7 || Length < 4) {
        throw Error("packet too long, length:" + length);
    }

    if (Length > networkBuffer.getBufferLength()) {
        //包没有收全
        return false;
    }

    networkBuffer.moveHeader(4);

    var is = new Taf.JceInputStream(new Taf.BinBuffer(networkBuffer.getBuffers(Length - 4)));

    networkBuffer.moveHeader(Length - 4);

    try {
        message.origin = TafPacket.BasePacket._readFrom(is);
    } catch (e) {
        console.error("packet parser error", e);
        throw Error("packet parser error");
    }
    message.sFuncName = message.origin.sFuncName;

    return true;
}
